<?php
/** Synthetic local software fixtures only; never a genuine volunteer research packet. */
require_once __DIR__.'/workflow-fixture.php';
function rd_test_task(string $rid,string $kind): array {
    foreach(wf_tasks($rid) as $task)if($task['kind']===$kind)return $task;
    throw new RuntimeException('Missing derivation fixture task '.$kind);
}
function rd_test_plan(string $rid,array $task,bool $computational=false): array {
    $d=wf_test_payload($rid,$task);
    $d['tasks']=[['key'=>'arithmetic','title'=>'Inspect synthetic sample arithmetic','objective'=>'Read the supplied fictional sample and retain a bounded source-based account.',
        'deliverable'=>'A clearly labeled synthetic narrative with cited inputs, units and any worked reasoning.','acceptance'=>'Retain the supplied input scope, explicit units and honest limitations.',
        'evidence_needs'=>'Inspect only the supplied synthetic inputs and distinguish them from real observations.','stopping_rule'=>'Stop after the supplied counts, resulting bounded reasoning and limits are documented.',
        'computational'=>$computational,'builds_tool'=>false,'dependencies'=>[]]];
    return rs_test_materials($d,$task);
}
