        'authors'=>'Repository QA fixture','publication_date'=>'','publisher'=>'','doi'=>'','edition'=>'v1','metadata_note'=>'Invented local software-test material; no external publication, DOI or scholarly inspection exists.','use'=>'used'];
    $d['evidence']['claims'][0]=['id'=>'c1','statement'=>$statement,'kind'=>'inference','support'=>'supported','confidence'=>'moderate','confidence_reason'=>'The provided counts and written reasoning support this fictional text-level schema exercise only.',
        'derivation'=>'The retained text reasons from 2 / 8 = 0.25 to 25 percent without claiming tool execution.','limitations'=>$d['limitations'],'counterevidence'=>'No external research or contrary-source search was performed; this is an invented local test input.',
        'basis_result_ids'=>$task['kind']==='synthesis'?array_keys(wf_evidence_results($task)):[],
        'links'=>[['source_id'=>'s1','relation'=>'supports','locator'=>'Provided synthetic QA input v1, counts sentence','excerpt'=>$input,'explanation'=>'The supplied fictional counts are the original inputs, with their explicit synthetic limitation; the retained steps explain the derived percentage.']]];
    $d['evidence']['search_log']=[['query'=>'Inspect the complete supplied fictional sample counts','where'=>'Synthetic QA input v1 in the sources field','result'=>'Read the complete provided text; no external source inspection, tools or real-world research is claimed.']];
    $d['evidence']['derivations']=[['version'=>1,'type'=>'model_derived','id'=>'share','title'=>'Synthetic sample share, model-derived only','claim_ids'=>['c1'],'source_ids'=>['s1'],
        'inputs'=>[['id'=>'part','value'=>2,'unit'=>'items','source_id'=>'s1','source_locator'=>'Provided synthetic input v1, covered count','extraction'=>'The fictional sample has 2 covered items.'],
            ['id'=>'whole','value'=>8,'unit'=>'items','source_id'=>'s1','source_locator'=>'Provided synthetic input v1, total count','extraction'=>'The fictional sample has 8 total items.']],
        'formula'=>'share_percent = part / whole * 100','steps'=>['Divide the covered count by the total: 2 / 8 = 0.25, a dimensionless fraction.','Express the same fraction in percent: 0.25 * 100 = 25 percent.'],
        'outputs'=>[['id'=>'share_percent','value'=>25,'unit'=>'percent']],
