function rd_test_review(string $rid,array $task,string $verdict='assessed'): array {
    $d=wf_test_payload($rid,$task,$verdict==='assessed'?'verified':'needs_correction');$d['corrections']=[];$d['evidence']['derivation_reviews']=[];
    foreach($d['evidence']['review_checks'] as &$audit){
        $record=one('SELECT metadata FROM workflow_submissions WHERE id=?',[$audit['result_id']]);$e=json_decode($record['metadata'],true)['evidence'];
        foreach($audit['source_checks'] as &$check){foreach($e['claims'] as $claim)if($claim['id']===$audit['claim_id'])foreach($claim['links'] as $link)if($link['source_id']===$check['source_id']){$check['excerpt']=$link['excerpt'];$check['locator']=$link['locator'];}
            $check['assessment']='Read the retained fictional fixture text and its scope only; this is a synthetic test, not real independent scientific review.';}unset($check);
    }unset($audit);
    foreach(rd_targets($task) as $target)$d['evidence']['derivation_reviews'][]=['version'=>1,'task_id'=>$target['task']['id'],'result_id'=>$target['result']['id'],'derivation_id'=>$target['derivation']['id'],'verdict'=>$verdict,
        'method'=>$verdict==='assessed'?'Synthetic independent-role fixture: inspect source extraction, units, formula and the retained model-worked steps; no code or scientific verification is claimed.':'Synthetic correction fixture: source extraction or worked reasoning needs clarification before the derivation can be assessed.',
        'worked_steps'=>$verdict==='assessed'?['Check the supplied fictional counts in text: 2 divided by 8 is 0.25, or 25 percent.']:[],
        'observed_outputs'=>$verdict==='assessed'?$target['derivation']['outputs']:[],
        'limitations'=>'This is a predefined software-test assessment and not an actual scientific review, executed calculation or computational reproduction.'];
    return rs_test_materials($d,$task);
}
function rd_test_create(string $label,string $calculationHelp='prepare_review',bool $computational=false): array {
    $made=create_research(['title'=>'[QA] '.$label.' '.uid(),'question'=>'Inspect a bounded fictional sample with cited inputs and explicitly limited reasoning. This is synthetic software testing only.',
        'category_id'=>one('SELECT id FROM categories LIMIT 1')['id'],'calculation_help'=>$calculationHelp,'external_tools'=>'none','terms'=>1]);
    $rid=$made['id'];moderate('request',$rid,'Approved','Synthetic arithmetic contract fixture; no scientific approval is implied.');
    $plan=rd_test_task($rid,'planning');wf_test_submit($rid,$plan['id'],rd_test_plan($rid,$plan,$computational),str_repeat('a',64));
    return ['id'=>$rid,'task'=>rd_test_task($rid,'research')];
}
